{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Telmisartan, a lipophilic benzimidazole-containing drug with high molecular weight and low aqueous solubility, has an absolute oral bioavailability of 43% in healthy volunteers, directly supporting F ≥ 20% for the query despite unfavorable physicochemical priors.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Bosentan, a high-molecular-weight drug with multiple aromatic/heteroaromatic rings and polar groups, shows an absolute oral bioavailability of 46% (95% CI 30–72%) after oral suspension versus IV, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Imatinib, a high-molecular-weight oral kinase inhibitor with multiple aromatic rings and ionizable groups, is rapidly and completely absorbed with a mean absolute bioavailability of 98%, demonstrating that such physicochemical features do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Silodosin, a moderately high-molecular-weight drug with basic amine and multiple polar groups, has an absolute oral bioavailability of 32.2% in fasted healthy men, still above the 20% threshold and supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Amlodipine, which contains ester and amine functionalities, has an absolute oral bioavailability of 81% in men, supporting that ester-containing query molecules can have high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability well above 20% (32–98%), strongly supporting a high F prediction for the query. The unfavorable physicochemical prior is outweighed by direct, transferable experimental evidence, though uncertainty remains due to the query's very high molecular weight, TPSA, rotatable bond count, and lack of an exact structural match.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "No analogue with the exact hexyl carbamate/guanidine/ester prodrug motif was tested.",
    "Solubility, dissolution, and first-pass ester hydrolysis behavior of the query were not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

